-- OPTION (...) on every DML statement, derived-table column names, MERGE ... INSERT DEFAULT VALUES
UPDATE t SET a = 1 OPTION (MAXDOP 1);

DELETE FROM t WHERE a = 1 OPTION (RECOMPILE);

INSERT INTO t SELECT a FROM s OPTION (HASH JOIN);

MERGE INTO t AS tgt USING (SELECT 1 AS id) AS src (id) ON tgt.id = src.id WHEN MATCHED THEN UPDATE SET tgt.a = 1 WHEN NOT MATCHED BY TARGET AND src.id > 0 THEN INSERT DEFAULT VALUES OUTPUT $action INTO @log OPTION (LOOP JOIN);

SELECT * FROM (SELECT 1, 2) AS s (a, b);

SELECT * FROM t JOIN (SELECT 1) AS s (a) ON 1 = 1;

SELECT a FROM t OPTION (RECOMPILE);
